            { kind: "read", promptUk: "Як заборонити зайві поля в тілі запиту?", promptEn: "How do you forbid extra fields in a request body?", language: "go", code: "dec := json.NewDecoder(r.Body)", options: ["dec.DisallowUnknownFields() перед Decode", "це неможливо в encoding/json", "достатньо малої літери полів", "omitempty блокує зайві ключі"], correctIndex: 0, explanationUk: "Суворий декодер.", explanationEn: "A strict decoder." }
